#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

long long mode(const long long arr[], size_t n) {
    if (n == 0) return 0;

    long long best_val = arr[0];
    size_t best_count = 1;

    for (size_t i = 0; i < n; ++i) {
        long long val = arr[i];
        size_t count = 1;

        for (size_t j = i + 1; j < n; ++j) {
            long long other = arr[j];
            if (val == other) {
                count++;
            }
        }

        if (count > best_count || (count == best_count && val < best_val)) {
            best_val = val;
            best_count = count;
        }
    }

    return best_val;
}

int main(void) {
    // Test 1: Basic case
    long long arr1[] = {1, 2, 2, 3, 3, 3, 4};
    size_t n1 = sizeof(arr1) / sizeof(arr1[0]);
    printf("%lld\n", mode(arr1, n1));

    // Test 2: Tie - return smallest
    long long arr2[] = {5, 5, 6, 6, 7};
    size_t n2 = sizeof(arr2) / sizeof(arr2[0]);
    printf("%lld\n", mode(arr2, n2));

    // Test 3: Single element
    long long arr3[] = {42};
    size_t n3 = sizeof(arr3) / sizeof(arr3[0]);
    printf("%lld\n", mode(arr3, n3));

    // Test 4: All equal
    long long arr4[] = {9, 9, 9, 9};
    size_t n4 = sizeof(arr4) / sizeof(arr4[0]);
    printf("%lld\n", mode(arr4, n4));

    // Test 5: Negative numbers and zero
    long long arr5[] = {-1, 0, 0, -1, 2, -1};
    size_t n5 = sizeof(arr5) / sizeof(arr5[0]);
    printf("%lld\n", mode(arr5, n5));

    return 0;
}

