import java.util.*;

public class Solution {
    public static int mode(int[] arr) {
        if (arr.length == 0) {
            return 0;
        }
        Map<Integer, Integer> freq = new HashMap<>();
        for (int val : arr) {
            freq.put(val, freq.getOrDefault(val, 0) + 1);
        }
        int bestVal = arr[0];
        int bestFreq = freq.get(bestVal);
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int val = entry.getKey();
            int other = entry.getValue();
            if (other > bestFreq || (other == bestFreq && val < bestVal)) {
                bestVal = val;
                bestFreq = other;
            }
        }
        return bestVal;
    }

    public static void main(String[] args) {
        // Test 1: normal case
        int[] arr1 = {1, 2, 2, 3, 3, 3, 4};
        System.out.println(mode(arr1));

        // Test 2: tie, return smallest
        int[] arr2 = {5, 5, 6, 6, 7};
        System.out.println(mode(arr2));

        // Test 3: single element
        int[] arr3 = {42};
        System.out.println(mode(arr3));

        // Test 4: all equal (edge case)
        int[] arr4 = {9, 9, 9, 9};
        System.out.println(mode(arr4));

        // Test 5: negative numbers and zero
        int[] arr5 = {-1, 0, -1, 2, 0, -1, 0};
        System.out.println(mode(arr5));

        // Test 6: empty array (edge case)
        int[] arr6 = {};
        System.out.println(mode(arr6));
    }
}
